from collections import deque, defaultdict, Counter

def components(arr, target_test=lambda x: x!=1):
    H,W=len(arr),len(arr[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if (r,c) in seen or not target_test(arr[r][c]): continue
            col=arr[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for z in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    yy,xx=z
                    if 0<=yy<H and 0<=xx<W and z not in seen and target_test(arr[yy][xx]) and arr[yy][xx]==col:
                        seen.add(z); q.append(z)
            out.append((col,cells))
    return out

def norm(cells):
    r0=min(r for r,c in cells); c0=min(c for r,c in cells)
    return tuple(sorted((r-r0,c-c0) for r,c in cells))
def shape_str(cells):
    s=norm(cells); h=max(r for r,c in s)+1; w=max(c for r,c in s)+1
    return '/'.join(''.join('#' if (r,c) in s else '.' for c in range(w)) for r in range(h))
def canon(cells, reflect=False):
    pts=norm(cells); opts=[]
    for f in range(2 if reflect else 1):
      for rot in range(4):
        ls=[]
        for r,c in pts:
            if f: c=-c
            for _ in range(rot): r,c=c,-r
            ls.append((r,c))
        opts.append(norm(ls))
    return min(opts)

